CREATE TABLE IF NOT EXISTS "user" ("id" text PRIMARY KEY NOT NULL, "name" text NOT NULL, "email" text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, "image" text, "role" text NOT NULL DEFAULT 'admin', "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
ALTER TABLE "user" ADD COLUMN IF NOT EXISTS "role" text NOT NULL DEFAULT 'admin';
CREATE TABLE IF NOT EXISTS "session" ("id" text PRIMARY KEY NOT NULL, "expiresAt" timestamp NOT NULL, "token" text NOT NULL UNIQUE, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL);
CREATE TABLE IF NOT EXISTS "account" ("id" text PRIMARY KEY NOT NULL, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamp, "refreshTokenExpiresAt" timestamp, "scope" text, "password" text, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "verification" ("id" text PRIMARY KEY NOT NULL, "identifier" text NOT NULL, "value" text NOT NULL, "expiresAt" timestamp NOT NULL, "createdAt" timestamp DEFAULT now(), "updatedAt" timestamp DEFAULT now());
CREATE TABLE IF NOT EXISTS "truck" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "code" text NOT NULL, "plate" text NOT NULL, "brand" text NOT NULL, "model" text NOT NULL, "year" integer, "capacity_tons" numeric(10,2), "fuel_type" text DEFAULT 'Diesel', "benchmark_km_l" numeric(10,2), "current_km" numeric(12,2) NOT NULL DEFAULT 0, "status" text NOT NULL DEFAULT 'active', "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "driver" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "user_id" text, "name" text NOT NULL, "email" text, "phone" text, "employee_id" text, "assigned_truck_id" integer, "status" text NOT NULL DEFAULT 'active', "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "transport_operation" ("id" serial PRIMARY KEY, "user_id" text NOT NULL, "truck_id" integer, "driver_id" integer, "operation_date" date NOT NULL, "truck_code" text NOT NULL, "driver_name" text NOT NULL, "city" text NOT NULL, "km" numeric(12,2) NOT NULL, "tons" numeric(12,2) NOT NULL, "liters" numeric(12,2) NOT NULL, "trips" numeric(10,2) NOT NULL DEFAULT 1, "status" text NOT NULL DEFAULT 'concluida', "notes" text, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "fuel_record" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "truck_id" integer, "driver_id" integer, "record_date" date NOT NULL, "odometer" numeric(12,2), "km" numeric(12,2) NOT NULL, "liters" numeric(12,2) NOT NULL, "price_per_liter" numeric(10,3) NOT NULL DEFAULT 0, "total_cost" numeric(12,2) NOT NULL DEFAULT 0, "station" text, "fuel_type" text NOT NULL DEFAULT 'Diesel', "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "maintenance_record" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "truck_id" integer NOT NULL, "maintenance_date" date NOT NULL, "maintenance_type" text NOT NULL DEFAULT 'corretiva', "problem" text NOT NULL, "description" text, "parts_cost" numeric(12,2) NOT NULL DEFAULT 0, "labor_cost" numeric(12,2) NOT NULL DEFAULT 0, "status" text NOT NULL DEFAULT 'aberta', "resolved_at" date, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "downtime_record" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "truck_id" integer NOT NULL, "started_at" date NOT NULL, "ended_at" date, "reason" text NOT NULL, "potential_revenue" numeric(12,2) NOT NULL DEFAULT 0, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "revenue" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "truck_id" integer, "operation_id" integer, "revenue_date" date NOT NULL, "description" text NOT NULL, "amount" numeric(12,2) NOT NULL, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "expense" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "truck_id" integer, "expense_date" date NOT NULL, "category" text NOT NULL, "description" text NOT NULL, "amount" numeric(12,2) NOT NULL, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "monthly_closure" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "reference_month" date NOT NULL, "status" text NOT NULL DEFAULT 'open', "closed_at" timestamp, "closed_by" text, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "incident" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "truck_id" integer, "driver_id" integer, "incident_date" date NOT NULL, "category" text NOT NULL, "description" text NOT NULL, "status" text NOT NULL DEFAULT 'aberta', "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "benchmark" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "truck_id" integer, "metric" text NOT NULL, "target_value" numeric(12,2) NOT NULL, "valid_from" date NOT NULL, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "notification" ("id" serial PRIMARY KEY, "user_id" text NOT NULL, "title" text NOT NULL, "message" text NOT NULL, "read_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "setting" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "setting_key" text NOT NULL, "setting_value" text NOT NULL, "updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "preventive_maintenance_rule" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "truck_id" integer, "name" text NOT NULL, "component" text NOT NULL, "interval_km" numeric(12,2), "interval_days" integer, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "alert_rule" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "category" text NOT NULL, "metric" text NOT NULL, "warning_percent" numeric(6,2) NOT NULL, "critical_percent" numeric(6,2) NOT NULL, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "revenue_rule" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "name" text NOT NULL, "billing_type" text NOT NULL, "origin" text, "destination" text, "rate" numeric(12,2) NOT NULL, "valid_from" date NOT NULL, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "expense_category" ("id" serial PRIMARY KEY, "owner_id" text NOT NULL, "name" text NOT NULL, "scope" text NOT NULL, "created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "audit_log" ("id" serial PRIMARY KEY, "user_id" text NOT NULL, "action" text NOT NULL, "entity" text NOT NULL, "entity_id" text, "metadata" text, "created_at" timestamp NOT NULL DEFAULT now());
